<?php

declare(strict_types=1);

namespace Sentinel\Services;

use DateTimeImmutable;
use Sentinel\Core\HttpException;
use Sentinel\Repositories\DeviceSessionRepository;

final class DeviceSessionManagementService
{
    private const TERMINAL=['ENDED','EXPIRED','REVOKED'];
    public function __construct(private readonly DeviceSessionRepository $sessions,private readonly AuditService $audit){}
    public function listSessions(array $filters=[]):array{if(array_diff(array_keys($filters),['device_id','employee_id','session_status'])!==[])throw HttpException::unprocessable('Invalid device session filters.','invalid_device_session_filters');return$this->sessions->listForCompany($filters);}
    public function getSession(string $id):array{return$this->sessions->findByIdForCompany($id)??throw HttpException::notFound('Device session not found.','device_session_not_found');}
    public function listDeviceSessions(string $deviceId):array{if($this->sessions->device($deviceId)===null)throw HttpException::notFound('Device not found.','device_not_found');return$this->sessions->listForDevice($deviceId);}
    public function startSession(array $input):array{$data=$this->fields($input);$device=$this->sessions->device((string)$data['device_id']);if($device===null)throw HttpException::notFound('Device not found.','device_not_found');if($device['device_status']!=='ACTIVE')throw HttpException::unprocessable('Device must be active to start a session.','invalid_device_status');if(!$this->sessions->employeeExists((string)$data['employee_id']))throw HttpException::notFound('Employee not found.','employee_not_found');$this->relationships($data);if($this->sessions->activeSessionForDevice((string)$data['device_id'])!==null)throw HttpException::conflict('Device already has an active session.','device_session_conflict');$session=$this->sessions->createForCompany($data);$this->audit('started',(string)$session['device_session_id'],[],$session);return$session;}
    public function endSession(string $id,array $input):array{$before=$this->getSession($id);if($before['session_status']!=='ACTIVE')throw HttpException::unprocessable('Only active sessions can be ended.','invalid_session_transition');$status=$input['session_status']??'ENDED';if(!in_array($status,self::TERMINAL,true))throw HttpException::unprocessable('Session status is invalid.','invalid_session_status');$ended=$this->date($input['ended_at']??null,'ended_at');if($ended<$this->date($before['started_at'],'started_at'))throw HttpException::unprocessable('Ended at must not precede started at.','invalid_date_relationship');$updated=$this->sessions->updateForCompany($id,['session_status'=>$status,'ended_at'=>$input['ended_at'],'last_seen_at'=>$input['last_seen_at']??$input['ended_at']])??throw HttpException::notFound('Device session not found.','device_session_not_found');$this->audit('ended',$id,$before,$updated);return$updated;}
    private function fields(array $input):array{ $allowed=['device_id','device_assignment_id','employee_id','employee_assignment_id','shift_assignment_id','site_id','started_at'];if(array_diff(array_keys($input),$allowed)!==[])throw HttpException::unprocessable('Invalid device session fields.','invalid_device_session_request');foreach(['device_id','employee_id']as$f)if(!isset($input[$f]))throw HttpException::unprocessable('Session field is required.','invalid_'.$f);$data=$input;foreach(['device_assignment_id','employee_assignment_id','shift_assignment_id','site_id']as$f)$data[$f]??=null;foreach(['device_id','employee_id','device_assignment_id','employee_assignment_id','shift_assignment_id','site_id']as$f)if(isset($data[$f])&&$data[$f]!==null)$data[$f]=$this->id($data[$f],$f);$data['started_at']=$data['started_at']??date('Y-m-d H:i:s');$this->date($data['started_at'],'started_at');$data['session_status']='ACTIVE';$data['ended_at']=null;$data['last_seen_at']=$data['started_at'];return$data;}
    private function relationships(array $data):void{if($data['device_assignment_id']!==null){$assignment=$this->sessions->deviceAssignment((string)$data['device_assignment_id']);if($assignment===null||$assignment['assignment_status']!=='ACTIVE'||$assignment['ends_at']!==null||(string)$assignment['device_id']!==(string)$data['device_id']||(string)$assignment['employee_id']!==(string)$data['employee_id'])throw HttpException::notFound('Device assignment not found.','device_assignment_not_found');if($data['employee_assignment_id']!==null&&(string)$assignment['employee_assignment_id']!==(string)$data['employee_assignment_id'])throw HttpException::unprocessable('Device assignment context does not match.','invalid_assignment_context');}if($data['employee_assignment_id']!==null){$assignment=$this->sessions->employeeAssignment((string)$data['employee_assignment_id']);if($assignment===null||(string)$assignment['employee_id']!==(string)$data['employee_id'])throw HttpException::notFound('Employee assignment not found.','employee_assignment_not_found');}if($data['shift_assignment_id']!==null){$shift=$this->sessions->shift((string)$data['shift_assignment_id']);if($shift===null||(string)$shift['employee_id']!==(string)$data['employee_id'])throw HttpException::notFound('Shift assignment not found.','shift_assignment_not_found');if($data['site_id']!==null&&(string)$shift['site_id']!==(string)$data['site_id'])throw HttpException::unprocessable('Shift site context does not match.','invalid_site_context');}if($data['site_id']!==null&&!$this->sessions->siteExists((string)$data['site_id']))throw HttpException::notFound('Site not found.','site_not_found');}
    private function id(mixed $value,string $field):int{if((!is_int($value)&&!(is_string($value)&&ctype_digit($value)))||(int)$value<1)throw HttpException::unprocessable('Session identifier is invalid.','invalid_'.$field);return(int)$value;}private function date(mixed $value,string $field):DateTimeImmutable{if(!is_string($value))throw HttpException::unprocessable('Session date is invalid.','invalid_'.$field);try{return new DateTimeImmutable($value);}catch(\Throwable){throw HttpException::unprocessable('Session date is invalid.','invalid_'.$field);}}private function audit(string $action,string $id,array $old,array $new):void{try{$this->audit->record('device_session',$action,$id,$old,$new);}catch(\Throwable){}}
}